class Check {
 class FakeAudio : IPetAudio {public int Plays,Stops,Peak,SampleCount;public uint Device;public bool Finished;public bool Done {get{return Finished;}}public void Play(short[] samples,uint device){Finished=false;Plays++;Device=device;SampleCount=samples.Length;Peak=0;foreach(short sample in samples)Peak=Math.Max(Peak,Math.Abs((int)sample));if(samples.Length==0)throw new Exception("Empty sound");}public void Stop(){Stops++;}public void Dispose(){Stop();}}
 static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Set(object o,string n,object v){o.GetType().GetField(n,flags).SetValue(o,v);}
 static object Get(object o,string n){return o.GetType().GetField(n,flags).GetValue(o);}
 static void Call(object o,string n){o.GetType().GetMethod(n,flags).Invoke(o,null);}
 static void Mood(object o,string value){var field=o.GetType().GetField("mood",flags);field.SetValue(o,Enum.Parse(field.FieldType,value));Set(o,"stateTime",0.0);}
 static string State(object o){return Get(o,"mood").ToString();}
 static void Step(object o,double dt,Point cursor){o.GetType().GetMethod("UpdatePet",flags).Invoke(o,new object[]{dt,cursor});}
 static Bitmap Frame(object o){return (Bitmap)o.GetType().GetMethod("DrawFrame",flags).Invoke(o,null);}
 static void Assert(bool value,string message){if(!value)throw new Exception(message);}
 [STAThread] static void Main(string[] args){try{if(args.Length>0&&args[0]=="--clone-menu-check"){CloneMenuInputCheck();return;}PolishTimingChecks();Run();Features();Clones();using(var child=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Application.ExecutablePath,"--clone-menu-check"){UseShellExecute=false})){if(!child.WaitForExit(15000)){child.Kill();throw new Exception("Clone menus starved UI input");}Assert(child.ExitCode==0,"Clone menu input check failed");}SocialChecks();WrappingChecks();MischiefChecks();UpdateCheck.Run();StartupChecks();FrameChecks();SpeechStabilityChecks();RapChecks();CharacterCheck.Run();ThemeCheck.Run();UiUpgradeCheck.Run();AudioFocusCheck.Run();}catch(Exception error){Console.WriteLine("FAIL: "+error.Message);Environment.Exit(1);}}
 static void CloneMenuInputCheck(){using(var pet=new Usagi())using(var timer=new Timer{Interval=900}){((PetSound)Get(pet,"sounds")).Enabled=false;pet.Shown+=(s,e)=>{Call(pet,"DuplicatePets");timer.Start();};timer.Tick+=(s,e)=>{timer.Stop();try{var pets=(System.Collections.Generic.List<Usagi>)typeof(Usagi).GetField("livePets",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);Assert(pets.Count==5,"Expected original and four live clones");foreach(var actor in pets.ToArray()){Assert((double)Get(actor,"lastTick")>.3,"An animated clone was starved by other pets");var menu=(ContextMenuStrip)Get(actor,"menu");menu.Show(new Point(500,500));Application.DoEvents();Assert(menu.Visible&&menu.Items.Contains((ToolStripItem)Get(actor,"cleanupMenu")),"Clone action menu did not open");menu.Close();}Console.WriteLine("PASS: original and four animated clones open right-click menus without starving UI.");}finally{Call(pet,"ClearClones");pet.Close();}};Application.Run(pet);}}
