 static void Clones(){using(var pet=new Usagi()){
   ((PetSound)Get(pet,"sounds")).Enabled=false;var area=Screen.PrimaryScreen.WorkingArea;Set(pet,"x",area.Left+area.Width/2.0-pet.Width/2);Set(pet,"y",(double)area.Bottom-pet.Height+8);
