   try{
     foreach(var pet in new[]{big,small}){((PetSound)Get(pet,"sounds")).Enabled=false;Set(pet,"x",area.Left+area.Width/2.0-pet.Width/2);Set(pet,"y",(double)area.Bottom-pet.Height+8);Set(pet,"idleTime",0.0);Set(pet,"greetCooldown",0.0);Set(pet,"nextSpeechTime",0.0);Set(pet,"socialBreak",0.0);Mood(pet,"Walk");}
     var rests=new System.Collections.Generic.HashSet<double>();for(int i=0;i<12;i++){big.GetType().GetMethod("Change",flags).Invoke(big,new object[]{Enum.Parse(big.GetType().GetField("mood",flags).FieldType,"Sit")});double duration=(double)Get(big,"restDuration");Assert(duration>=1.4&&duration<=4.5,"Rest duration outside natural range");rests.Add(duration);}Assert(rests.Count>8,"Rest duration is synchronized");Mood(big,"Walk");
     Set(big,"scale",1.3f);Set(small,"scale",.75f);Set(small,"x",(double)Get(big,"x")+70);Set(big,"direction",1);Set(small,"direction",-1);Set(big,"moving",true);
     Assert(SocialStep(big,.02,far,false),"Meeting did not start greeting");Assert((double)Get(big,"greetLeft")>0&&(double)Get(small,"greetLeft")>0,"Greeting was not mutual");double position=(double)Get(big,"x");SocialStep(big,.2,far,false);Assert((double)Get(big,"x")==position,"Greeting did not stop walking");SocialStep(small,.3,far,false);Assert((string)Get(small,"words")=="야하~!","Greeting reply missing");double greetingWait=(double)Get(small,"nextSpeechTime");big.GetType().GetMethod("BeginGreeting",flags).Invoke(big,new object[]{small});SocialStep(small,.3,far,false);Assert((double)Get(small,"nextSpeechTime")==greetingWait,"Social greeting bypassed automatic speech cooldown");
     Call(big,"CancelSocial");Call(small,"CancelSocial");Set(big,"socialBreak",0.0);Set(small,"socialBreak",0.0);Mood(big,"Walk");Mood(small,"Walk");Set(big,"moving",true);Set(big,"speed",60.0);Set(small,"followCooldown",0.0);Set(small,"x",(double)Get(big,"x")-230);Assert(SocialStep(small,.02,far,false)&&(bool)Get(small,"following"),"Small pet did not follow larger leader");double before=(double)Get(small,"x");for(int i=0;i<40;i++)SocialStep(small,.02,far,false);Assert((double)Get(small,"x")>before+20,"Follower did not approach queue position");
     Call(small,"CancelSocial");Set(small,"socialBreak",0.0);Set(small,"playCooldown",0.0);Mood(small,"Walk");var cursor=new Point((int)(double)Get(small,"x")+small.Width/2+75,(int)(double)Get(small,"y")+small.Height-55);SocialStep(small,.02,cursor,true);Assert((double)Get(small,"playLeft")>0,"Cursor game did not start");before=(double)Get(small,"x");for(int i=0;i<35;i++)SocialStep(small,.02,cursor,false);Assert((double)Get(small,"x")>before,"Pet did not approach cursor");Set(small,"playLeft",1.0);before=(double)Get(small,"x");for(int i=0;i<45;i++)SocialStep(small,.02,cursor,false);Assert((double)Get(small,"x")<before,"Pet did not run away from cursor");
     Call(small,"CancelSocial");Set(small,"socialBreak",0.0);Set(small,"idleTime",10.0);Mood(big,"Sleep");Mood(small,"Drowsy");SocialStep(small,.02,far,false);Assert(Get(small,"napFriend")==big,"Pet did not gather beside sleeper");for(int i=0;i<330&&State(small)!="Sleep";i++)SocialStep(small,.02,far,false);Assert(State(small)=="Sleep","Gathering pet never slept");
     Mood(big,"Sleep");Mood(small,"Sleep");Set(big,"wakeDelay",-1.0);Set(small,"wakeDelay",-1.0);Set(small,"x",(double)Get(big,"x")+350);var wakeCursor=new Point((int)(double)Get(big,"x")+big.Width/2,(int)(double)Get(big,"y")+big.Height-55);foreach(var pet in new[]{big,small})pet.GetType().GetMethod("UpdateSleepWake",flags).Invoke(pet,new object[]{.016,wakeCursor,true});Assert(State(big)=="Sleep"&&State(small)=="Sleep","Group woke simultaneously on first mouse movement");Assert((double)Get(big,"wakeDelay")<(double)Get(small,"wakeDelay"),"Nearby pet does not wake first");for(int i=0;i<450;i++)foreach(var pet in new[]{big,small})pet.GetType().GetMethod("UpdateSleepWake",flags).Invoke(pet,new object[]{.016,wakeCursor,false});Assert(State(big)=="Stretch"&&State(small)=="Stretch","Staggered wake did not complete");Mood(small,"Sleep");small.GetType().GetMethod("BeginPointer",flags).Invoke(small,new object[]{wakeCursor});Assert(State(small)=="Stretch","Direct touch did not wake immediately");Set(small,"pointerDown",false);
     Mood(small,"Walk");Set(small,"idleTime",0.0);Set(small,"playLeft",2.0);Call(small,"OfferFood");Assert((double)Get(small,"playLeft")==0&&!(bool)Get(small,"following"),"Feeding did not cancel social behavior");
